const crypto = require('crypto');
const E = (e) => `${e.code ?? e.name} | ${String(e.message).split('\n')[0]}`;
const t = (l, f) => { try { console.log(l, '->', f()); } catch (e) { console.log(l, '-> THROW', E(e)); } };
t('pbkdf2 rfc6070 1', () => crypto.pbkdf2Sync('password', 'salt', 1, 20, 'sha1').toString('hex'));
t('pbkdf2 rfc6070 4096', () => crypto.pbkdf2Sync('password', 'salt', 4096, 20, 'sha1').toString('hex'));
t('pbkdf2 rfc6070 long', () => crypto.pbkdf2Sync('passwordPASSWORDpassword', 'saltSALTsaltSALTsaltSALTsaltSALTsalt', 4096, 25, 'sha1').toString('hex'));
t('pbkdf2 rfc6070 nul', () => crypto.pbkdf2Sync('pass\0word', 'sa\0lt', 4096, 16, 'sha1').toString('hex'));
for (const d of ['sha256', 'sha512', 'sha3-256', 'md5']) t(`pbkdf2 ${d}`, () => crypto.pbkdf2Sync('pw', 'salt', 1000, 64, d).toString('hex'));
t('pbkdf2 bad digest', () => crypto.pbkdf2Sync('pw', 's', 1, 8, 'nope'));
t('pbkdf2 iterations 0', () => crypto.pbkdf2Sync('pw', 's', 0, 8, 'sha1'));
t('pbkdf2 no digest', () => crypto.pbkdf2Sync('pw', 's', 1, 8));
crypto.pbkdf2('pw', 'salt', 1000, 32, 'sha256', (e, k) => console.log('pbkdf2 cb ->', e && e.code, k && k.toString('hex')));
t('hkdf rfc5869 1', () => Buffer.from(crypto.hkdfSync('sha256', Buffer.from('0b'.repeat(22), 'hex'), Buffer.from('000102030405060708090a0b0c', 'hex'), Buffer.from('f0f1f2f3f4f5f6f7f8f9', 'hex'), 42)).toString('hex'));
t('hkdf empty salt/info', () => Buffer.from(crypto.hkdfSync('sha256', Buffer.from('0b'.repeat(22), 'hex'), '', '', 42)).toString('hex'));
t('hkdf sha512 str', () => Buffer.from(crypto.hkdfSync('sha512', 'key', 'salt', 'info', 100)).toString('base64'));
t('hkdf too long', () => crypto.hkdfSync('sha256', 'k', 's', 'i', 255 * 32 + 1));
t('hkdf returns ArrayBuffer', () => crypto.hkdfSync('sha256', 'k', 's', 'i', 8) instanceof ArrayBuffer);
crypto.hkdf('sha256', 'k', 's', 'i', 16, (e, k) => console.log('hkdf cb ->', e && e.code, Buffer.from(k).toString('hex')));
t('scrypt rfc7914 1', () => crypto.scryptSync('', '', 64, { N: 16, r: 1, p: 1 }).toString('hex'));
t('scrypt rfc7914 2', () => crypto.scryptSync('password', 'NaCl', 64, { N: 1024, r: 8, p: 16 }).toString('hex'));
t('scrypt default', () => crypto.scryptSync('pw', 'salt', 32).toString('hex'));
t('scrypt cost alias', () => crypto.scryptSync('pw', 'salt', 16, { cost: 1024, blockSize: 8, parallelization: 1 }).toString('hex'));
t('scrypt N not pow2', () => crypto.scryptSync('pw', 's', 16, { N: 1000 }));
t('scrypt maxmem exceeded', () => crypto.scryptSync('pw', 's', 16, { N: 2 ** 16, r: 8, maxmem: 32 * 1024 * 1024 }));
t('scrypt maxmem ok', () => crypto.scryptSync('pw', 's', 16, { N: 2 ** 16, r: 8, maxmem: 128 * 1024 * 1024 }).toString('hex'));
t('scrypt N 2^20 default maxmem', () => crypto.scryptSync('pw', 's', 16, { N: 2 ** 20 }));
const t0 = Date.now(); const sk = crypto.scryptSync('correct horse', 'salt', 32, { N: 2 ** 14, r: 8, p: 1 }); console.error(`TIMING scrypt N=2^14 r=8: ${Date.now() - t0} ms`); console.log('scrypt N=2^14 ->', sk.toString('hex'));
const t1 = Date.now(); const sk2 = crypto.scryptSync('pw', 'salt', 32, { N: 2 ** 17, r: 8, p: 1, maxmem: 256 * 1024 * 1024 }); console.error(`TIMING scrypt N=2^17 r=8: ${Date.now() - t1} ms`); console.log('scrypt N=2^17 ->', sk2.toString('hex'));
crypto.scrypt('pw', 'salt', 16, (e, k) => console.log('scrypt cb ->', e && e.code, k && k.toString('hex')));
const tp = Date.now(); crypto.pbkdf2Sync('pw', 'salt', 600000, 32, 'sha256'); console.error(`TIMING pbkdf2 600k sha256: ${Date.now() - tp} ms`);
